1|import "server-only";
2|import { parseCapUsd, turnstilePair, usable } from "@/server/guard/env";
3|import type { TurnstilePair } from "@/server/guard/env";
4|
5|// Upload env, read once per request. Jev is optional: without a usable key
6|// the free path classifies with the contributor model alone. Missing
7|// required env means 503 unavailable, never unauthenticated spend.
8|export interface UploadEnv extends TurnstilePair {
9|  upstashUrl: string;
10|  upstashToken: string;
11|  metaKey: string;
12|  jevKey?: string;
13|  sessionSecret: string;
14|  ipSalt: string;
15|  spendCapMicro: number;
16|}
17|
18|const URL_NAMES = "UPSTASH_REDIS_REST_URL|KV_REST_API_URL";
19|const TOKEN_NAMES = "UPSTASH_REDIS_REST_TOKEN|KV_REST_API_TOKEN";
20|
21|const REQUIRED = [
22|  "BLOB_READ_WRITE_TOKEN",
23|  "META_API_KEY",
24|  "SESSION_SECRET",
25|  "IP_HASH_SALT",
26|] as const;
27|
28|export function readUploadEnv(from: NodeJS.ProcessEnv = process.env): UploadEnv {
29|  const candidate = usable(from.UPSTASH_REDIS_REST_URL) ?? usable(from.KV_REST_API_URL);
30|  const upstashUrl = candidate?.startsWith("https://") ? candidate : undefined;
31|  const upstashToken = usable(from.UPSTASH_REDIS_REST_TOKEN) ?? usable(from.KV_REST_API_TOKEN);
32|  const missing = [
33|    upstashUrl ? null : URL_NAMES,
34|    upstashToken ? null : TOKEN_NAMES,
35|    ...REQUIRED.filter((k) => !usable(from[k])),
36|  ].filter((m): m is string => m !== null);
37|  if (missing.length > 0) throw new Error(`missing upload env: ${missing.join(",")}`);
38|  const jevKey = usable(from.JEV_API_KEY);
39|  return {
40|    upstashUrl: upstashUrl as string,
41|    upstashToken: upstashToken as string,
42|    metaKey: from.META_API_KEY as string,
43|    ...(jevKey ? { jevKey } : {}),
44|    sessionSecret: from.SESSION_SECRET as string,
45|    ipSalt: from.IP_HASH_SALT as string,
46|    spendCapMicro: Math.round(parseCapUsd(from.SPEND_CAP_USD, 10) * 1_000_000),
47|    ...turnstilePair(from),
48|  };
49|}

