42|
43|// Same ordinals and hash input as the Gutenberg path, without the
44|// Gutenberg source block: uploads are reader books, not shelf books.
45|export function buildUploadBook(
46|  id: string,
47|  title: string,
48|  author: string | null,
49|  drafts: { title: string; paragraphs: string[] }[],
50|): UploadBook {
51|  const chapters: Chapter[] = [];
52|  const paragraphs: Paragraph[] = [];
53|  let n = 0;
54|  drafts.forEach((draft, index) => {
55|    const ch = index + 1;
56|    const start_n = n + 1;
57|    draft.paragraphs.forEach((text, k) => {
58|      n += 1;
59|      paragraphs.push({ id: paragraphId(ch, k + 1), ch, n, text });
60|    });
61|    chapters.push({ ch, title: draft.title, start_n, end_n: n });
62|  });
63|  const textVersion = `sha256:${createHash("sha256").update(canonicalLines(paragraphs)).digest("hex")}`;
64|  // The reader prints the author, so a missing one becomes Unknown here.
65|  return { id, title, author: author ?? "Unknown", chapters, paragraphs, textVersion };
66|}
