68|export interface CreateArgs {
69|  kv: KV;
70|  store: UploadStore;
71|  meta: MetaClient;
72|  body: UploadCreateBody;
73|  path: "free" | "byok";
74|  anonId: string;
75|  day: string;
76|  quotaKeys: { ip: string; anon: string } | null;
77|  spendCapMicro: number;
78|}
