80|// Validate on the cleaned text first so user errors never take quota;
81|// the judge runs after the spend reserve, and its failure just keeps the
82|// deterministic chapters. Any throw after the reserve refunds everything.
83|export async function createUpload(args: CreateArgs): Promise<{ id: string; chapters: number; parts: number }> {
84|  const preview = cleanDeterministic(args.body.title, args.body.sections);
85|  if (preview.chapters.length === 0 || preview.chapters.length > UPLOAD_MAX_CHAPTERS) {
86|    throw new UploadFailure("bad_request");
87|  }
88|  const limit = args.path === "free" ? FREE_BOOK_MAX_WORDS : BYOK_BOOK_MAX_WORDS;
89|  if (countChapterWords(preview.chapters) > limit) throw new UploadFailure("too_long");
90|
91|  let quotaTaken = false;
92|  let reservation: SpendReservation | null = null;
93|  try {
94|    if (args.path === "free" && args.quotaKeys) {
95|      const taken = await takeDualQuota(args.kv, args.quotaKeys, {
96|        limit: FREE_BOOKS_PER_PERSON,
97|        ttlSec: BOOK_QUOTA_TTL_SEC,
98|      });
99|      if (!taken.ok) throw new UploadFailure("daily_books_reached");
100|      quotaTaken = true;
101|      const spent = await reserveSpend(args.kv, {
102|        amountMicro: UPLOAD_RESERVE_MICRO,
103|        day: args.day,
104|        spendCapMicro: args.spendCapMicro,
105|        dailySpendCapMicro: UPLOAD_DAILY_SPEND_CAP_MICRO,
106|        dailyKey: uploadDailySpendKey(args.day),
107|      });
108|      if (!spent.ok) throw new UploadFailure("daily_budget_reached");
109|      reservation = spent.reservation;
110|    }
111|
112|    const usage = emptyUsage();
113|    const cleaned = await cleanSections(args.body.title, args.body.sections, createCleanJudge(args.meta));
114|    const llm = cleaned.report.llm;
115|    if (llm && llm.model !== "unknown") {
116|      usage.metaRequests += 1;
117|      usage.metaPrompt += llm.promptTokens;
118|      usage.metaCached += llm.cachedTokens;
119|      usage.metaCompletion += llm.completionTokens;
120|    }
121|    if (cleaned.chapters.length === 0) throw new UploadFailure("bad_request");
122|
123|    const id = newUploadId();
124|    const book = buildUploadBook(id, args.body.title, args.body.author, cleaned.chapters);
125|    const parts = splitChapterParts(book.chapters);
126|    const job: UploadJob = {
127|      v: 1,
128|      id,
129|      path: args.path,
130|      anonId: args.path === "free" ? args.anonId : null,
131|      day: args.day,
132|      createdAt: Date.now(),
133|      title: book.title,
134|      author: book.author,
135|      textVersion: book.textVersion,
136|      chapters: book.chapters.map((c) => ({ ch: c.ch, title: c.title, start_n: c.start_n, end_n: c.end_n })),
137|      parts,
138|      doneParts: [],
139|      status: "working",
140|      usage,
141|      reservedMicro: args.path === "free" ? UPLOAD_RESERVE_MICRO : 0,
142|      quotaIp: args.path === "free" && args.quotaKeys ? args.quotaKeys.ip : null,
143|      quotaAnon: args.path === "free" && args.quotaKeys ? args.quotaKeys.anon : null,
144|      costMicro: null,
145|    };
146|    await args.store.saveJson(uploadBookPath(id), JSON.stringify(book));
147|    await saveUploadJob(args.kv, job);
148|    return { id, chapters: book.chapters.length, parts: parts.length };
149|  } catch (e) {
150|    // Both refunds are best effort and never throw, so the original error
151|    // always survives. A Blob orphan here ages out via the cleanup cron.
152|    await reservation?.release();
153|    if (quotaTaken && args.quotaKeys) await refundDualQuota(args.kv, args.quotaKeys);
154|    if (e instanceof UploadFailure) throw e;
155|    throw new UploadFailure("unavailable");
156|  }
