32|function clampSceneText(scene: SceneInput): SceneInput {
33|  return {
34|    start_n: scene.start_n,
35|    end_n: scene.end_n,
36|    title: scene.title.slice(0, 200),
37|    summary: scene.summary.slice(0, 2000),
38|    characters: scene.characters.slice(0, 12).map((c) => c.slice(0, 120)),
39|  };
