78|// Contributor-only emotion for BYOK and for the free path without a Jev
79|// key. Mirrors the override prompt, plus the intensity/tempo questions Jev
80|// would have answered. Only the 8 ids; a bad vector fails the scene.
81|const DIRECT_SCHEMA = {
82|  type: "object",
83|  properties: {
84|    vector: {
85|      type: "object",
86|      properties: Object.fromEntries(EMOTIONS.map((id) => [id, { type: "number" }])),
87|      required: [...EMOTIONS],
88|      additionalProperties: false,
89|    },
90|    intensity: { type: "number" },
91|    tempo: { type: "number" },
92|    reason: { type: "string" },
93|  },
94|  required: ["vector", "intensity", "tempo", "reason"],
95|  additionalProperties: false,
96|};
