1|import "server-only";
2|import { del, get, list, put } from "@vercel/blob";
3|
4|// Private Blob store for uploads: book text belongs to the reader, so
5|// paths carry the unguessable job id, blobs stay private, and only this
6|// server module reads them back. Routes never return Blob URLs.
7|export interface UploadStore {
8|  saveJson(path: string, json: string): Promise<void>;
9|  readText(path: string): Promise<string | null>;
10|  remove(path: string): Promise<void>;
11|  listAll(prefix: string): Promise<{ pathname: string; uploadedAt: number }[]>;
12|}
13|
14|const BLOB_TIMEOUT_MS = 8_000;
15|
16|export function createUploadStore(): UploadStore {
17|  return {
18|    async saveJson(path: string, json: string): Promise<void> {
19|      await put(path, json, {
20|        access: "private",
21|        addRandomSuffix: false,
22|        allowOverwrite: true,
23|        contentType: "application/json",
24|        abortSignal: AbortSignal.timeout(BLOB_TIMEOUT_MS),
25|      });
26|    },
27|    async readText(path: string): Promise<string | null> {
28|      // Null when the path was never written; anything else throws.
29|      const found = await get(path, {
30|        access: "private",
31|        useCache: false,
32|        abortSignal: AbortSignal.timeout(BLOB_TIMEOUT_MS),
33|      });
34|      if (!found || found.stream === null) return null;
35|      return await new Response(found.stream).text();
36|    },
37|    async remove(path: string): Promise<void> {
38|      await del(path, { abortSignal: AbortSignal.timeout(BLOB_TIMEOUT_MS) });
39|    },
40|    async listAll(prefix: string): Promise<{ pathname: string; uploadedAt: number }[]> {
41|      const out: { pathname: string; uploadedAt: number }[] = [];
42|      let cursor: string | undefined;
43|      for (;;) {
44|        const page = await list({
45|          prefix,
46|          limit: 1000,
47|          ...(cursor ? { cursor } : {}),
48|          abortSignal: AbortSignal.timeout(BLOB_TIMEOUT_MS),
49|        });
50|        for (const blob of page.blobs) out.push({ pathname: blob.pathname, uploadedAt: blob.uploadedAt.getTime() });
51|        if (!page.hasMore) break;
52|        cursor = page.cursor;
53|      }
54|      return out;
55|    },
56|  };
57|}

