143|// Every scene gets an emotion; per-scene failures record the error and
144|// keep final null like Oz, so one bad scene never fails the book.
145|export async function classifyPart(
146|  scenes: (SceneInput & Pick<Scene, "id" | "ch">)[],
147|  texts: string[],
148|  ctx: { bookTitle: string; chapterTitle: string },
149|  deps: { meta: MetaClient; jev: JevClient | null },
150|  usage: UploadUsage,
151|): Promise<SceneEmotion[]> {
152|  const metaUsage: ClassifyMetaUsage = {
153|    model: deps.meta.model,
154|    requests: 0,
155|    promptTokens: 0,
156|    cachedTokens: 0,
157|    completionTokens: 0,
158|    costUsd: 0,
159|  };
160|  const out = await runPool(scenes, 4, async (scene, index) => {
161|    const text = texts[index] ?? "";
162|    if (deps.jev === null) return classifySceneDirect(deps.meta, scene, text, usage);
163|    const emotion = await classifyScene(scene as Scene, text, ctx.bookTitle, ctx.chapterTitle, deps as { jev: JevClient; meta: MetaClient }, metaUsage);
164|    if (emotion.jev) {
165|      usage.jevInput += emotion.jev.input_tokens;
166|      usage.jevOutput += emotion.jev.output_tokens;
167|      usage.jevRequests += 1;
168|    }
169|    return emotion;
170|  });
171|  usage.metaRequests += metaUsage.requests;
172|  usage.metaPrompt += metaUsage.promptTokens;
173|  usage.metaCached += metaUsage.cachedTokens;
174|  usage.metaCompletion += metaUsage.completionTokens;
175|  return out;
