5|// Blob wrappers. Paths are deterministic and public; routes return URLs,
6|// never bytes. @vercel/blob reads BLOB_READ_WRITE_TOKEN from env.
7|const BLOB_TIMEOUT_MS = 8_000;
8|
9|// Each call fails fast inside the 120 s route budget (Meta takes up to
10|// 100 s), so a slow Blob still leaves time for the refund and unlock.
11|export function createBlobStore(): ImageStore {
12|  return {
13|    // list stands in for head: a deterministic path has no known URL
14|    // until the store prefix is resolved, so match the exact pathname.
15|    async findUrl(path: string): Promise<string | null> {
16|      const page = await list({ prefix: path, limit: 10, abortSignal: AbortSignal.timeout(BLOB_TIMEOUT_MS) });
17|      return page.blobs.find((b) => b.pathname === path)?.url ?? null;
18|    },
19|    async save(path: string, bytes: Uint8Array): Promise<string> {
20|      const blob = await put(path, Buffer.from(bytes), {
21|        access: "public",
22|        addRandomSuffix: false,
23|        allowOverwrite: false,
24|        contentType: "image/webp",
25|        cacheControlMaxAge: 31536000,
26|        abortSignal: AbortSignal.timeout(BLOB_TIMEOUT_MS),
27|      });
28|      return blob.url;
29|    },
30|  };
