132|export function section(id: string, label: string, paras: number, wordsPerPara: number): RawSection {
133|  const blocks = [];
134|  for (let p = 0; p < paras; p++) {
135|    const words = [];
136|    for (let w = 0; w < wordsPerPara; w++) words.push(WORDS[(p + w) % WORDS.length]);
137|    blocks.push({ text: words.join(" "), heading: false });
138|  }
139|  return { id, href: `${id}.xhtml`, linear: true, types: [], docTitle: null, navLabel: label, blocks };
