149|  headers: Record<string, string> = {},
150|): Request {
151|  return new Request(url, {
152|    method: "POST",
153|    headers: { "content-type": "application/json", ...headers },
154|    body: typeof body === "string" ? body : JSON.stringify(body),
155|  });
