158|// Merges every Set-Cookie pair into one Cookie header for the next call.
159|export function cookiesFrom(res: Response, prev = ""): string {
160|  const found = typeof res.headers.getSetCookie === "function" ? res.headers.getSetCookie() : [];
161|  const pairs = found.map((c) => c.split(";")[0] as string);
162|  const jar = new Map<string, string>();
163|  for (const part of [...prev.split(";"), ...pairs]) {
164|    const eq = part.indexOf("=");
165|    if (eq > 0) jar.set(part.slice(0, eq).trim(), part.slice(eq + 1).trim());
166|  }
167|  return [...jar.entries()].map(([k, v]) => `${k}=${v}`).join("; ");
