76|function deterministicFilter(bookTitle: string, sections: RawSection[]): DeterministicState {
77|  const removed: RemovedItem[] = [];
78|  const flagged: CleanReport["flagged"] = [];
79|  const merged: CleanReport["merged"] = [];
80|  const pushRemoved = (sec: RawSection, rule: string, kind: string, reason: string): void => {
81|    removed.push(removedFor(sec, rule, kind, reason));
82|  };
