183|export async function cleanSections(
184|  bookTitle: string,
185|  sections: RawSection[],
186|  judge?: Judge,
187|): Promise<{ chapters: CleanChapter[]; report: CleanReport }> {
188|  const state = deterministicFilter(bookTitle, sections);
189|  const { removed, flagged, confident } = state;
190|  const pushRemoved = (sec: RawSection, rule: string, kind: string, reason: string): void => {
191|    removed.push(removedFor(sec, rule, kind, reason));
192|  };
193|
194|  let llm: CleanReport["llm"] = null;
195|  const ambiguous = state.kept.filter((sec) => !confident.has(sec.id));
196|  if (ambiguous.length > 0 && judge !== undefined) {
197|    let result: JudgeResult | null = null;
198|    try {
