208|        model: result.model,
209|        promptTokens: result.promptTokens,
210|        completionTokens: result.completionTokens,
211|        cachedTokens: result.cachedTokens,
212|        costUsd: result.costUsd,
213|        fallbackUsed: result.fallbackUsed,
214|      };
215|      const byId = new Map(result.sections.map((v) => [v.id, v]));
216|      const contentIds = new Set(
217|        ambiguous.filter((sec) => byId.get(sec.id)?.verdict === "content" || confident.has(sec.id)).map((sec) => sec.id),
218|      );
219|      for (const c of state.kept) if (confident.has(c.id)) contentIds.add(c.id);
220|      const after: RawSection[] = [];
221|      ambiguous.forEach((sec) => {
222|        const verdict = byId.get(sec.id);
223|        if (verdict === undefined || verdict.verdict === "content") {
224|          after.push(sec);
225|          return;
226|        }
227|        if (verdict.verdict === "uncertain") {
228|          flagged.push({ sectionId: sec.id, reason: short(verdict.reason, 120) });
229|          after.push(sec);
230|          return;
231|        }
232|        const at = state.kept.indexOf(sec);
233|        const before = state.kept.slice(0, at).some((s) => contentIds.has(s.id));
234|        const behind = state.kept.slice(at + 1).some((s) => contentIds.has(s.id));
