238|          return;
239|        }
240|        pushRemoved(sec, "llm", verdict.kind, verdict.reason);
241|      });
242|      const keptIds = new Set(after.map((s) => s.id).concat([...confident]));
243|      state.kept = state.kept.filter((sec) => confident.has(sec.id) || keptIds.has(sec.id));
