252|            state.kept = [{ ...firstKept, blocks: firstKept.blocks.slice(cut) }, ...state.kept.slice(1)];
253|          }
254|        }
255|      }
256|      if (state.kept.length > 0 && tailCut > 0) {
257|        const lastKept = state.kept[state.kept.length - 1];
258|        if (lastKept !== undefined) {
