260|          // blocks rule 10 removes right after. Cut only the fresh middle
261|          // and skip the entry entirely when nothing fresh remains. Head
262|          // cuts need no guard: no deterministic rule trims heads.
263|          const overlap = deterministicTailOverlap(state.kept, state.kept.length - 1);
