269|              ...state.kept.slice(0, -1),
270|              { ...lastKept, blocks: [...lastKept.blocks.slice(0, start), ...lastKept.blocks.slice(end)] },
271|            ];
272|          }
273|        }
274|      }
275|    }
276|  }
277|
278|  return finishBook(bookTitle, state, llm);
