7|
8|const KINDS = [
9|  "content",
10|  "front_matter",
11|  "title_page",
12|  "copyright",
13|  "contents",
14|  "advertisement",
15|  "transcriber_note",
16|  "license",
17|  "colophon",
18|  "about_author",
19|  "other",
20|];
