415|export function readEpubSections(
416|  bytes: Uint8Array,
417|  parse: XmlParser = browserParse,
418|): Pick<EpubPackage, "title" | "author" | "sections"> {
419|  const { title, author, sections } = openEpub(bytes, parse, { checkMimetype: false, strictSpine: true });
420|  return { title, author, sections };
