423|export function parseEpub(bytes: Uint8Array): EpubBook {
424|  const { title, author, sections, cover } = openEpub(bytes, browserParse, {
425|    checkMimetype: true,
426|    strictSpine: false,
427|  });
428|  const { chapters } = cleanDeterministic(title, sections);
429|  let words = 0;
430|  const kept = chapters.slice(0, 500);
431|  for (const chapter of kept) {
432|    for (const paragraph of chapter.paragraphs) words = countWords(paragraph, words);
433|  }
434|  return { title, author, chapters: kept.map((chapter) => chapter.title), words, cover };
