79|function isPart(value: unknown): value is UploadPart {
80|  if (typeof value !== "object" || value === null) return false;
81|  const p = value as Record<string, unknown>;
82|  return (
83|    Number.isSafeInteger(p.ch) &&
84|    (p.ch as number) >= 1 &&
85|    Number.isSafeInteger(p.part) &&
86|    (p.part as number) >= 1 &&
87|    Number.isSafeInteger(p.startN) &&
88|    Number.isSafeInteger(p.endN) &&
89|    (p.startN as number) <= (p.endN as number)
90|  );
91|}
92|
93|function isUsage(value: unknown): value is UploadUsage {
94|  if (typeof value !== "object" || value === null) return false;
95|  return (["metaPrompt", "metaCached", "metaCompletion", "metaRequests", "jevInput", "jevOutput", "jevRequests"] as const).every(
96|    (k) => typeof (value as Record<string, unknown>)[k] === "number",
97|  );
