100|// Defensive read: Redis is trusted but a corrupt value must not crash the
101|// route. Returns the job, or null when missing or unparseable.
102|export function parseUploadJob(raw: string | null): UploadJob | null {
103|  if (raw === null) return null;
104|  let json: unknown;
105|  try {
106|    json = JSON.parse(raw);
107|  } catch {
108|    return null;
109|  }
110|  if (typeof json !== "object" || json === null) return null;
111|  const j = json as Record<string, unknown>;
112|  if (j.v !== 1 || !isUploadId(j.id)) return null;
113|  if (j.path !== "free" && j.path !== "byok") return null;
114|  if (j.anonId !== null && typeof j.anonId !== "string") return null;
115|  if (typeof j.day !== "string" || typeof j.createdAt !== "number") return null;
116|  if (typeof j.title !== "string" || typeof j.author !== "string") return null;
117|  if (typeof j.textVersion !== "string") return null;
118|  if (!Array.isArray(j.chapters) || !Array.isArray(j.parts) || !Array.isArray(j.doneParts)) return null;
119|  if (!j.parts.every(isPart) || !j.doneParts.every((d) => typeof d === "string")) return null;
120|  if (j.status !== "working" && j.status !== "done" && j.status !== "failed") return null;
121|  if (!isUsage(j.usage)) return null;
122|  if (typeof j.reservedMicro !== "number") return null;
123|  if (j.quotaIp !== null && typeof j.quotaIp !== "string") return null;
124|  if (j.quotaAnon !== null && typeof j.quotaAnon !== "string") return null;
125|  if (j.costMicro !== null && typeof j.costMicro !== "number") return null;
126|  for (const c of j.chapters) {
127|    if (typeof c !== "object" || c === null) return null;
128|    const ch = c as Record<string, unknown>;
129|    if (!Number.isSafeInteger(ch.ch) || typeof ch.title !== "string") return null;
130|    if (!Number.isSafeInteger(ch.start_n) || !Number.isSafeInteger(ch.end_n)) return null;
131|  }
132|  return json as UploadJob;
133|}
134|
135|export async function loadUploadJob(kv: KV, id: string): Promise<UploadJob | null> {
136|  return parseUploadJob(await kv.get(uploadJobKey(id)));
137|}
138|
139|export async function saveUploadJob(kv: KV, job: UploadJob): Promise<void> {
140|  await kv.set(uploadJobKey(job.id), JSON.stringify(job));
141|  await kv.expire(uploadJobKey(job.id), UPLOAD_JOB_TTL_SEC);
