1|import "server-only";
2|import { timingSafeEqual } from "node:crypto";
3|import { UPLOAD_TTL_DAYS } from "@/core/uploads";
4|import { usable } from "@/server/guard/env";
5|import { createUploadStore, type UploadStore } from "./blob";
6|
7|// Deletes upload blobs older than the TTL. Job state in Redis expires on
8|// its own; only Blob needs sweeping. One failure never stops the rest.
9|export async function cleanupUploads(store: UploadStore, nowMs: number = Date.now()): Promise<{ deleted: number }> {
10|  const cutoff = nowMs - UPLOAD_TTL_DAYS * 24 * 3600 * 1000;
11|  const blobs = await store.listAll("uploads/");
12|  let deleted = 0;
13|  for (const blob of blobs) {
14|    if (blob.uploadedAt >= cutoff) continue;
15|    try {
16|      await store.remove(blob.pathname);
17|      deleted += 1;
18|    } catch {
19|      // The next daily run retries.
20|    }
21|  }
22|  return { deleted };
23|}
24|
25|function matchesBearer(auth: string, secret: string): boolean {
26|  const expected = `Bearer ${secret}`;
27|  if (auth.length !== expected.length) return false;
28|  return timingSafeEqual(Buffer.from(auth), Buffer.from(expected));
29|}
30|
31|// Vercel cron calls this daily with CRON_SECRET as the Bearer [REDACTED] Any
32|// auth failure answers 404 so the route stays hidden.
33|export async function handleCleanup(
34|  req: Request,
35|  deps: { store?: UploadStore; secret?: string } = {},
36|): Promise<Response> {
37|  const secret = deps.secret ?? usable(process.env.CRON_SECRET);
38|  if (!secret || !matchesBearer(req.headers.get("authorization") ?? "", secret)) {
39|    return Response.json({ status: "error", code: "not_found" }, { status: 404 });
40|  }
41|  try {
42|    const out = await cleanupUploads(deps.store ?? createUploadStore());
43|    return Response.json({ status: "ok", deleted: out.deleted });
44|  } catch {
45|    console.error("upload cleanup failed");
46|    return Response.json({ status: "error", code: "unavailable" }, { status: 503 });
47|  }
