1|import "server-only";
2|import { createHmac, timingSafeEqual } from "node:crypto";
3|import { usable } from "./env";
4|
5|// Neutral human cookie, readable on every /api route. The old chat-only
6|// name stays accepted during transition; only the new one is issued.
7|export const HUMAN_COOKIE = "human_ok";
8|export const LEGACY_HUMAN_COOKIE = "chat_human";
9|const HUMAN_TTL_SEC = 2 * 3600;
10|
11|function sign(name: string, expiry: number, secret: string): string {
12|  return createHmac("sha256", secret).update(`${name}:${expiry}`).digest("hex");
13|}
14|
15|export function issueHumanCookie(secret: string, nowSec = Math.floor(Date.now() / 1000)): string {
16|  const expiry = nowSec + HUMAN_TTL_SEC;
17|  return `${HUMAN_COOKIE}=${expiry}.${sign(HUMAN_COOKIE, expiry, secret)}; Path=/api; HttpOnly; Secure; SameSite=Lax; Max-Age=${HUMAN_TTL_SEC}`;
18|}
19|
20|export function parseHumanCookie(header: string | null | undefined): string | null {
21|  if (!header) return null;
22|  let legacy: string | null = null;
23|  for (const part of header.split(";")) {
24|    const eq = part.indexOf("=");
25|    if (eq < 0) continue;
26|    const name = part.slice(0, eq).trim();
27|    if (name === HUMAN_COOKIE) return part.slice(eq + 1).trim();
28|    if (name === LEGACY_HUMAN_COOKIE) legacy = part.slice(eq + 1).trim();
29|  }
30|  return legacy;
31|}
32|
33|// True only with a valid signature and an unexpired timestamp. Comparison
34|// runs in constant time so a forged cookie reveals nothing about the secret.
35|export function verifyHumanCookie(
36|  value: string | null | undefined,
37|  secret: string,
38|  nowSec = Math.floor(Date.now() / 1000),
39|): boolean {
40|  if (!value) return false;
41|  const dot = value.indexOf(".");
42|  if (dot < 1) return false;
43|  const expiry = Number(value.slice(0, dot));
44|  if (!Number.isSafeInteger(expiry) || expiry <= nowSec) return false;
45|  const sig = value.slice(dot + 1);
46|  // Outstanding cookies signed the legacy name, so try both.
47|  for (const name of [HUMAN_COOKIE, LEGACY_HUMAN_COOKIE]) {
48|    const expected = sign(name, expiry, secret);
49|    if (sig.length === expected.length && timingSafeEqual(Buffer.from(sig), Buffer.from(expected))) {
50|      return true;
51|    }
52|  }
53|  return false;
54|}
