57|
58|// Without both keys the check is skipped so dev works without keys.
59|export function warnTurnstileSkippedOnce(): void {
60|  if (warnedOnce) return;
61|  warnedOnce = true;
62|  console.warn("turnstile not configured, skipping");
63|}
