69|// False on any failure: network, non-2xx, bad JSON, or success: false.
70|// Never throws, and never includes the token or response text anywhere.
71|export async function verifyTurnstile(
72|  token: string,
73|  ip: string,
74|  secret: string,
75|  fetchFn: typeof fetch = fetch,
76|): Promise<boolean> {
77|  // "unknown" is our own placeholder, not a client address: omit it.
78|  const params = new URLSearchParams({ secret, response: token });
79|  if (ip !== "unknown") params.set("remoteip", ip);
